curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>" -d "types=public_channel&limit=1000" | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        print(c['id'], c['name'])
else:
    print('ERROR:', data)
"

curl -s -X POST "https://slack.com/api/conversations.history?token=<TOKEN>" -d "channel=C_LAUNCH&limit=999" | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['messages']:
        print(m['ts'], m.get('type'), m.get('user'), m.get('text','')[:200])
else:
    print('ERROR:', data)
"

